export type CEFRLevel = "A1" | "A2" | "B1" | "B2" | "C1";
export type PracticeMode = "translation" | "daily" | "exam";

export interface SentenceItem {
  /** English prompt — always 2 sentences. */
  english: string;
  /** German answer — always 2 sentences, matching the English. */
  german: string;
  /** Vietnamese prompt — always 2 sentences, matching the English. */
  vietnamese?: string;
  /** Spanish prompt — always 2 sentences, matching the English. */
  spanish?: string;
  note: string;
  keywords?: string[];
}

export interface Topic {
  id: string;
  title: string;
  sentences: SentenceItem[];
}

